  private void DrawStar(Graphics g) {            // Path for the outer shape            using (GraphicsPath path = new GraphicsPath()) {                var center = new PointF(Width / 2, Height / 2); // Get the middle of the rectangle                var outerRadius = Math.Min(Width, Height) / 2;                var innerRadius = outerRadius / 2;// outerRadius - FrameSize + BorderSize * 2;                // Offset Shape Rotation                double stepRad = (360 / pointsCount).DegToRadians();                var angleRadOffset = GetOffsetAngle(PointsCount).DegToRadians();                // Collect star points                List<PointF> shape = new List<PointF>();                for (var i = 0; i < pointsCount; i++) {                    // get outer point                    shape.Add( new PointF(                        center.X + outerRadius * (float)Math.Cos(i * stepRad + angleRadOffset),                        center.Y + outerRadius * (float)Math.Sin(i * stepRad + angleRadOffset)                    ));                    // get inner point                    shape.Add(new PointF(                        center.X + innerRadius * (float)Math.Cos(i * stepRad + stepRad / 2 + angleRadOffset),                        center.Y + innerRadius * (float)Math.Sin(i * stepRad + stepRad / 2 + angleRadOffset)                    ));                }                var starPoints = shape.ToArray();                // Center the Shape to ClientRectangle                if (!pointsCount.IsEven()) {                    // Center the Shape to ClientRectangle                    var angleAlpha = (360 / pointsCount).DegToRadians();                    var shapeHeight1 = outerRadius * (1 + Math.Cos(angleAlpha / 2));                    var shapeHeight2 = innerRadius * (1 + Math.Cos(angleAlpha / 2));                    var offsetY1 = (Height - shapeHeight1) / 2;                    var offsetY2 = (Height - shapeHeight1) / 2;                    for (var i = 0; i < starPoints.Length; i++) {                        starPoints[i].Y += (int)offsetY1;                    }                }                // Define path with the geometry information only                path.StartFigure();                path.AddPolygon(starPoints);                path.CloseFigure();                shape = null;                Region = new Region(path);                if (BorderSize > 0) {                    using (Pen pen = new Pen(BorderColor, BorderSize)) {                        if (BorderType != OutlineStyle.Plná) {                            pen.DashStyle = Translate.GetDashStyle(BorderType); ;                        }                        g.DrawPath(pen, path);                    }                }            }        }//Debug    private void DrawStar2(Graphics g) {            // Path for the outer shape            using (GraphicsPath path1 = new GraphicsPath(), path2 = new GraphicsPath()) {                var center = new PointF(Width / 2, Height / 2); // Get the middle of the rectangle                var outerRadius = Math.Min(Width, Height) / 2;                var innerRadius = outerRadius / 2;// outerRadius - FrameSize + BorderSize * 2;                // Get total points of Star                var piontsTotal = pointsCount * 2;                // Create field of points                var shape1 = new PointF[pointsCount];                var shape2 = new PointF[pointsCount];                //Console.WriteLine("DrawNgon:\n\trect:{0}\n\tx:{1}, {2}\n\tr:{3}\n\tpointsCount:{4}\n\tstepAngle:{5}", rect, x, y, r, pointsCount, stepAngle);                // Offset Shape Rotation                double stepRad = (360 / pointsCount).DegToRadians();                var angleRadOffset = stepRad / 2;                // Collect points on circle                for (var i = 0; i < pointsCount; i++) {                                        // get outer point                    shape1[i] = new PointF(                        center.X + outerRadius * (float)Math.Cos(i * stepRad),                        center.Y + outerRadius * (float)Math.Sin(i * stepRad)                    );                    // get inner point                    shape2[i] = new PointF(                        center.X + innerRadius * (float)Math.Cos(i * stepRad + angleRadOffset),                        center.Y + innerRadius * (float)Math.Sin(i * stepRad + angleRadOffset)                    );                    //Console.WriteLine("\t\t({0})point:{1} isEven:{2}", i, shape1[i], i.IsEven());                }                path1.StartFigure();                path1.AddPolygon(shape1);                path1.CloseFigure();                path2.StartFigure();                path2.AddPolygon(shape2);                path2.CloseFigure();                using (Pen pen1 = new Pen(Color.Red, 2)) {                    g.DrawPath(pen1, path1);                }                using (Pen pen2 = new Pen(Color.Green, 2)) {                    g.DrawPath(pen2, path2);                }                for (var i = 0; i < shape1.Length; i++) {                    // Draw Text                    PointF p1 = shape1[i];                    using (StringFormat sf = new StringFormat() {                        Alignment = StringAlignment.Center,                        LineAlignment = StringAlignment.Center                    }) {                        var rect1 = new RectangleF(p1.X-20, p1.Y-20, 40, 40);                        using (SolidBrush brush = new SolidBrush(Color.Black)) {                            g.DrawString(i.ToString(), new Font(FontFamily.GenericSansSerif, 20.0F), brush, rect1, sf);                        }                    }                }                for (var i = 0; i < shape2.Length; i++) {                    // Draw Text                    PointF p2 = shape2[i];                    using (StringFormat sf = new StringFormat() {                        Alignment = StringAlignment.Center,                        LineAlignment = StringAlignment.Center                    }) {                        var rect1 = new RectangleF(p2.X - 20, p2.Y - 20, 40, 40);                        using (SolidBrush brush = new SolidBrush(Color.Black)) {                            g.DrawString(i.ToString(), new Font(FontFamily.GenericSansSerif, 20.0F), brush, rect1, sf);                        }                    }                }            }        }